/// Lesson sections for the info page — never shown on the practice screen.
const List<TechniqueSection> setFillDoublesLesson = [
  TechniqueSection(
    title: "Why it matters",
    body:
        "R R L L on the kit is two notes on one drum before the hands move on, so the fill can travel fast while each hand moves only once per pair. It is the pad sheet \"Doubles Fill\" with drums under it.",
  ),
  TechniqueSection(
    title: "How to play it",
    body:
        "Rock eighths for three bars, crash on the one of bar 1. In the fill bar line 1 plays two beats of doubles on the snare, beat 3 on the high tom and beat 4 on the floor tom; the kick keeps 1 and 3. Both notes of a pair go on the same drum and sound equally loud, then the next pair moves.",
  ),
  TechniqueSection(
    title: "Practice tips",
    body:
        "Line 2 starts with eighth-note doubles on snare and high tom and switches to sixteenth doubles on mid tom and floor tom. Line 4 accents the first note of every pair between high tom and floor tom; line 7 starts with an accented quarter on the high tom and runs down mid tom, floor tom and second floor tom. Line 8 puts the thirty-second doubles on the floor tom and returns to the snare. Toms accept any tom and the crash any crash, so a kit with fewer drums plays the sheet too: the mid tom and the second floor tom go to the nearest tom you have.",
  ),
  TechniqueSection(
    title: "Where you hear it",
    body:
        "Classic rock fills and the first fill most teachers hand out: R R L L down the toms, crash on one.",
  ),
];
